B.amp=new A.bS("Retention","Local data remains until you delete it, clear site/app storage, or uninstall. We keep no server-side learner database. Cached static assets follow normal CDN/browser cache lifetimes.","\u062f\u0627\u062f\u0647\u0654 \u0645\u062d\u0644\u06cc \u062a\u0627 \u0648\u0642\u062a\u06cc \u062e\u0648\u062f\u062a\u0627\u0646 \u067e\u0627\u06a9 \u06a9\u0646\u06cc\u062f \u0645\u06cc\u200c\u0645\u0627\u0646\u062f. \u067e\u0627\u06cc\u06af\u0627\u0647\u200c\u062f\u0627\u062f\u0647\u0654 \u06cc\u0627\u062f\u06af\u06cc\u0631\u0646\u062f\u0647 \u0631\u0648\u06cc \u0633\u0631\u0648\u0631 \u0646\u062f\u0627\u0631\u06cc\u0645.")
B.amq=new A.bS("Internet use and international transfers","The app needs the Internet to download course content, paintings and pre-rendered Azure neural TTS voice clips from our static host (currently GitHub Pages, GitHub Inc., USA). Clips are app assets, not recordings of you. GitHub may log IP and browser metadata under its own privacy statement; we do not receive those logs. Azure Speech was used by us at build time to create clips; your device does not send your voice to Azure during normal play. Browser speech-to-text (microphone coach) may process audio on Google/Apple servers under their policies when you tap the mic.","\u0627\u067e \u0628\u0631\u0627\u06cc \u0645\u062d\u062a\u0648\u0627\u06cc \u062f\u0648\u0631\u0647\u060c \u062a\u0635\u0648\u06cc\u0631 \u0648 \u0635\u062f\u0627\u0647\u0627\u06cc \u0627\u0632\u067e\u06cc\u0634\u200c\u0633\u0627\u062e\u062a\u0647\u0654 Azure \u0628\u0647 \u0627\u06cc\u0646\u062a\u0631\u0646\u062a \u0646\u06cc\u0627\u0632 \u062f\u0627\u0631\u062f (\u0645\u06cc\u0632\u0628\u0627\u0646: GitHub Pages \u062f\u0631 \u0622\u0645\u0631\u06cc\u06a9\u0627). \u0627\u06cc\u0646 \u06a9\u0644\u06cc\u067e\u200c\u0647\u0627 \u062f\u0627\u0631\u0627\u06cc\u06cc \u0627\u067e\u200c\u0627\u0646\u062f \u0646\u0647 \u0635\u062f\u0627\u06cc \u0634\u0645\u0627. GitHub \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a IP \u0631\u0627 \u062b\u0628\u062a \u06a9\u0646\u062f\u061b \u0645\u0627 \u0622\u0646 \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u06cc\u0645. Azure \u062f\u0631 \u0632\u0645\u0627\u0646 \u0633\u0627\u062e\u062a \u06a9\u0644\u06cc\u067e \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0634\u062f\u0647\u061b \u0647\u0646\u06af\u0627\u0645 \u0628\u0627\u0632\u06cc \u0635\u062f\u0627\u06cc \u0634\u0645\u0627 \u0628\u0647 Azure \u0646\u0645\u06cc\u200c\u0631\u0648\u062f. \u06af\u0641\u062a\u0627\u0631 \u0628\u0647 \u0645\u062a\u0646 \u0645\u0631\u0648\u0631\u06af\u0631 \u0647\u0646\u06af\u0627\u0645 \u0632\u062f\u0646 \u0645\u06cc\u06a9\u0631\u0648\u0641\u0648\u0646 \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0631\u0648\u06cc \u0633\u0631\u0648\u0631\u0647\u0627\u06cc \u06af\u0648\u06af\u0644/\u0627\u067e\u0644 \u067e\u0631\u062f\u0627\u0632\u0634 \u0634\u0648\u062f.")
B.amr=new A.bS("Law","England and Wales law. We may update these terms; the date above is the latest version.","\u0642\u0627\u0646\u0648\u0646 \u0627\u0646\u06af\u0644\u0633\u062a\u0627\u0646 \u0648 \u0648\u0644\u0632. \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0628\u0647\u200c\u0631\u0648\u0632 \u0634\u0648\u062f\u061b \u062a\u0627\u0631\u06cc\u062e \u0628\u0627\u0644\u0627 \u0622\u062e\u0631\u06cc\u0646 \u0646\u0633\u062e\u0647 \u0627\u0633\u062a.")
B.amt=new A.bS("AI voices and pictures","Voices: Microsoft Azure AI Speech neural TTS (pre-rendered). Illustrations: original AI-assisted art for the app. All voices are AI-generated neural text-to-speech.","\u0635\u062f\u0627\u0647\u0627: Azure TTS. \u062a\u0635\u0648\u06cc\u0631\u0647\u0627: \u0647\u0646\u0631 \u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u0628\u0627 \u06a9\u0645\u06a9 \u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06cc. \u0647\u0645\u0647\u0654 \u0635\u062f\u0627\u0647\u0627 \u0628\u0627 \u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06cc \u0633\u0627\u062e\u062a\u0647 \u0634\u062f\u0647\u200c\u0627\u0646\u062f.")
B.amu=new A.bS("Characters are fictional","All characters, family names, schools, nurseries, estate agencies and other businesses in the stories (for example Hartley and Wren Homes, Primrose Lane Nursery, Maple Grove Primary) are fictional. Any likeness to real people or companies is unintended. Paintings and avatars are original AI-assisted illustrations, not photos of real people or logos.","\u0647\u0645\u0647\u0654 \u0634\u062e\u0635\u06cc\u062a\u200c\u0647\u0627\u060c \u0645\u062f\u0627\u0631\u0633\u060c \u0645\u0647\u062f\u06a9\u0648\u062f\u06a9\u200c\u0647\u0627 \u0648 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u0647\u0627\u06cc \u062f\u0627\u0633\u062a\u0627\u0646 (\u0645\u062b\u0644 Hartley and Wren\u060c Primrose Lane\u060c Maple Grove) \u062e\u06cc\u0627\u0644\u06cc\u200c\u0627\u0646\u062f. \u0634\u0628\u0627\u0647\u062a \u0627\u062a\u0641\u0627\u0642\u06cc \u0628\u0647 \u0627\u0641\u0631\u0627\u062f \u06cc\u0627 \u0634\u0631\u06a9\u062a\u200c\u0647\u0627\u06cc \u0648\u0627\u0642\u0639\u06cc \u0646\u0627\u062e\u0648\u0627\u0633\u062a\u0647 \u0627\u0633\u062a. \u062a\u0635\u0648\u06cc\u0631\u0647\u0627 \u0639\u06a9\u0633 \u0627\u0641\u0631\u0627\u062f \u0648\u0627\u0642\u0639\u06cc \u06cc\u0627 \u0644\u0648\u06af\u0648 \u0646\u06cc\u0633\u062a\u0646\u062f.")
B.amw=new A.bS("Payments (later)","The app is free in beta; no payment is taken. If subscriptions start, Apple/Google/Stripe will process payments under their terms; we will update this policy and show clear prices, renewal and cancellation (including DMCC cooling-off) before charging.","\u062f\u0631 \u0628\u062a\u0627 \u0631\u0627\u06cc\u06af\u0627\u0646 \u0627\u0633\u062a. \u0627\u06af\u0631 \u0627\u0634\u062a\u0631\u0627\u06a9 \u0634\u0631\u0648\u0639 \u0634\u0648\u062f\u060c \u067e\u0631\u062f\u0627\u062e\u062a \u0627\u0632 \u0627\u067e\u0644/\u06af\u0648\u06af\u0644/Stripe \u0627\u0633\u062a \u0648 \u0627\u06cc\u0646 \u0633\u06cc\u0627\u0633\u062a \u0648 \u0642\u0648\u0627\u0646\u06cc\u0646 \u0644\u063a\u0648 \u0628\u0647\u200c\u0631\u0648\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f.")
B.amx=new A.bS(B.dL,B.P,B.qq)
B.amy=new A.bS("Speak with a parent","If you are under 13, please use the app with a parent or carer.","\u0627\u06af\u0631 \u0632\u06cc\u0631 \u06f1\u06f3 \u0633\u0627\u0644 \u0647\u0633\u062a\u06cc\u062f\u060c \u0628\u0627 \u0648\u0627\u0644\u062f \u06cc\u0627 \u0633\u0631\u067e\u0631\u0633\u062a \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f.")
B.amA=new A.bS("Beta and pricing","The app is in a free beta. Features may change. Example prices on the Premium screen are illustrations only \u2014 no payment is taken until billing is switched on and these terms are updated.","\u0627\u067e \u062f\u0631 \u0628\u062a\u0627 \u0631\u0627\u06cc\u06af\u0627\u0646 \u0627\u0633\u062a. \u0642\u06cc\u0645\u062a\u200c\u0647\u0627\u06cc \u0646\u0645\u0648\u0646\u0647 \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0646\u0645\u0627\u06cc\u0634\u200c\u0627\u0646\u062f \u0648 \u062a\u0627 \u0641\u0639\u0627\u0644 \u0634\u062f\u0646 \u067e\u0631\u062f\u0627\u062e\u062a\u060c \u067e\u0648\u0644\u06cc \u06af\u0631\u0641\u062a\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.")
B.amB=new A.bS("Agreement","These terms are between you and [PLACEHOLDER: BUSINESS LEGAL NAME] (contact [PLACEHOLDER: PRIVACY CONTACT EMAIL]). By using New Life UK you agree to them. If you do not agree, do not use the app.","\u0627\u06cc\u0646 \u0634\u0631\u0627\u06cc\u0637 \u0645\u06cc\u0627\u0646 \u0634\u0645\u0627 \u0648 [PLACEHOLDER: BUSINESS LEGAL NAME] (\u062a\u0645\u0627\u0633 [PLACEHOLDER: PRIVACY CONTACT EMAIL]) \u0627\u0633\u062a. \u0628\u0627 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0645\u06cc\u200c\u067e\u0630\u06cc\u0631\u06cc\u062f\u061b \u0648\u06af\u0631\u0646\u0647 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u06a9\u0646\u06cc\u062f.")
B.amD=new A.bS("Your rights","Under UK data protection law you can access, correct, erase, restrict or port personal data we hold (normally none on our servers; use Export / Delete below for on-device data), and complain to the ICO (ico.org.uk). DUAA: you can also raise a data-protection complaint with us at [PLACEHOLDER: PRIVACY CONTACT EMAIL]; we will acknowledge within 30 days and respond without undue delay.","\u0637\u0628\u0642 \u0642\u0627\u0646\u0648\u0646 \u0628\u0631\u06cc\u062a\u0627\u0646\u06cc\u0627 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0628\u0647 \u062f\u0627\u062f\u0647 \u062f\u0633\u062a\u0631\u0633\u06cc\u060c \u0627\u0635\u0644\u0627\u062d\u060c \u062d\u0630\u0641\u060c \u0645\u062d\u062f\u0648\u062f\u06cc\u062a \u06cc\u0627 \u0627\u0646\u062a\u0642\u0627\u0644 \u0628\u062e\u0648\u0627\u0647\u06cc\u062f (\u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0631\u0648\u06cc \u0633\u0631\u0648\u0631 \u0686\u06cc\u0632\u06cc \u0646\u06cc\u0633\u062a\u061b \u0627\u0632 \u062e\u0631\u0648\u062c\u06cc/\u062d\u0630\u0641 \u0632\u06cc\u0631 \u0628\u0631\u0627\u06cc \u062f\u0627\u062f\u0647\u0654 \u062f\u0633\u062a\u06af\u0627\u0647 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f) \u0648 \u0628\u0647 ICO \u0634\u06a9\u0627\u06cc\u062a \u06a9\u0646\u06cc\u062f. \u0634\u06a9\u0627\u06cc\u062a \u0628\u0647 \u0645\u0627: [PLACEHOLDER: PRIVACY CONTACT EMAIL] \u2014 \u0638\u0631\u0641 \u06f3\u06f0 \u0631\u0648\u0632 \u062a\u0623\u06cc\u06cc\u062f \u0648 \u067e\u0627\u0633\u062e \u0628\u062f\u0648\u0646 \u062a\u0623\u062e\u06cc\u0631 \u0646\u0627\u0631\u0648\u0627.")
B.amE=new A.bS("Trade marks","Brand and place names of real public services are used descriptively. New Life UK is used as a product name; see the compliance report for the UKIPO search note.","\u0646\u0627\u0645 \u062e\u062f\u0645\u0627\u062a \u0639\u0645\u0648\u0645\u06cc \u0648\u0627\u0642\u0639\u06cc \u0641\u0642\u0637 \u062a\u0648\u0635\u06cc\u0641\u06cc \u0627\u0633\u062a.")
B.amH=new A.bS("Not advice \u2014 immigration / legal / medical","New Life UK teaches English. It is not legal, medical, immigration, financial or professional advice. We are not regulated by the OISC. Visa Help Desk and Settlement content are general information and GOV.UK / OISC signposts only. For your own case use gov.uk and an OISC-regulated adviser. Career Packs are language practice, not job training. Certificates are not an accredited qualification or Home Office SELT test; CEFR levels are indicative only.","\u0645\u0634\u0627\u0648\u0631\u0647\u0654 \u062d\u0642\u0648\u0642\u06cc\u060c \u067e\u0632\u0634\u06a9\u06cc\u060c \u0645\u0647\u0627\u062c\u0631\u062a\u06cc \u06cc\u0627 \u0645\u0627\u0644\u06cc \u0646\u06cc\u0633\u062a. \u062a\u062d\u062a \u0646\u0638\u0627\u0631\u062a OISC \u0646\u06cc\u0633\u062a\u06cc\u0645. \u0648\u06cc\u0632\u0627 \u0648 \u0627\u0642\u0627\u0645\u062a \u0641\u0642\u0637 \u0627\u0637\u0644\u0627\u0639\u0627\u062a \u0639\u0645\u0648\u0645\u06cc \u0648 \u0627\u0631\u062c\u0627\u0639 \u0628\u0647 GOV.UK / \u0645\u0634\u0627\u0648\u0631 OISC \u0627\u0633\u062a. \u06af\u0648\u0627\u0647\u06cc\u200c\u0647\u0627 \u0645\u062f\u0631\u06a9 \u0631\u0633\u0645\u06cc \u06cc\u0627 SELT \u0646\u06cc\u0633\u062a\u0646\u062f.")
B.amI=new A.bS("Best interests and high privacy","If a child uses kid mode: progress stays only on this device; no child account; no ads; no tracking; no public leagues; geolocation off; no prompts to turn off privacy. Parents can delete the child profile or all local data any time.","\u062f\u0631 \u062d\u0627\u0644\u062a \u06a9\u0648\u062f\u06a9: \u067e\u06cc\u0634\u0631\u0641\u062a \u0641\u0642\u0637 \u0631\u0648\u06cc \u062f\u0633\u062a\u06af\u0627\u0647\u061b \u0628\u062f\u0648\u0646 \u062d\u0633\u0627\u0628 \u06a9\u0648\u062f\u06a9\u060c \u062a\u0628\u0644\u06cc\u063a\u060c \u0631\u062f\u06cc\u0627\u0628\u06cc\u060c \u0644\u06cc\u06af \u0639\u0645\u0648\u0645\u06cc\u061b \u0645\u0648\u0642\u0639\u06cc\u062a \u062e\u0627\u0645\u0648\u0634. \u0648\u0627\u0644\u062f \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u06cc\u0627 \u0647\u0645\u0647\u0654 \u062f\u0627\u062f\u0647 \u0631\u0627 \u067e\u0627\u06a9 \u06a9\u0646\u062f.")
B.amJ=new A.bS("Not affiliated","Not affiliated with or endorsed by any government body, charity, company or brand. Real services (gov.uk, NHS, 999/101, DVSA, Ofsted, Citizens Advice) are named only factually as places to get real help.","\u0648\u0627\u0628\u0633\u062a\u0647 \u06cc\u0627 \u0645\u0648\u0631\u062f \u062a\u0623\u06cc\u06cc\u062f \u0647\u06cc\u0686 \u0646\u0647\u0627\u062f \u062f\u0648\u0644\u062a\u06cc \u06cc\u0627 \u0628\u0631\u0646\u062f\u06cc \u0646\u06cc\u0633\u062a\u06cc\u0645. \u062e\u062f\u0645\u0627\u062a \u0648\u0627\u0642\u0639\u06cc \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0631\u0627\u0647\u0646\u0645\u0627\u06cc\u06cc \u0648\u0627\u0642\u0639\u06cc \u0646\u0627\u0645 \u0628\u0631\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.")
B.amK=new A.bS("Acceptable use","Do not misuse the app, attempt to break security, scrape content at scale, or harass others if community features appear later.","\u0627\u0632 \u0627\u067e \u0633\u0648\u0621\u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u06a9\u0646\u06cc\u062f\u060c \u0627\u0645\u0646\u06cc\u062a \u0631\u0627 \u0646\u0634\u06a9\u0646\u06cc\u062f \u0648 \u0645\u062d\u062a\u0648\u0627 \u0631\u0627 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u0627\u0646\u0628\u0648\u0647 \u06a9\u067e\u06cc \u0646\u06a9\u0646\u06cc\u062f.")
B.amL=new A.bS("What stays on your device","Progress (lessons, XP, gentle streaks, saved words, diary, settings), learner profiles (including kid-friendly profiles), calm-circle codes, and any name typed on a certificate stay in encrypted local storage on this device where the platform supports it (Hive + secure key on Android/iOS; browser storage on the PWA). A service worker or on-device cache may keep lesson files for offline use. This storage is strictly necessary for the features you chose, so no cookie-consent banner is required under PECR for essential storage. Clearing site data / app storage or using Delete my data below erases it; we cannot recover it.","\u067e\u06cc\u0634\u0631\u0641\u062a\u060c \u067e\u0631\u0648\u0641\u0627\u06cc\u0644\u200c\u0647\u0627 (\u0627\u0632 \u062c\u0645\u0644\u0647 \u06a9\u0648\u062f\u06a9)\u060c \u06a9\u062f\u0647\u0627\u06cc \u062d\u0644\u0642\u0647\u0654 \u0622\u0631\u0627\u0645 \u0648 \u0646\u0627\u0645 \u0631\u0648\u06cc \u06af\u0648\u0627\u0647\u06cc \u062f\u0631 \u062d\u0627\u0641\u0638\u0647\u0654 \u0645\u062d\u0644\u06cc \u0631\u0645\u0632\u06af\u0630\u0627\u0631\u06cc\u200c\u0634\u062f\u0647 (\u062f\u0631 \u0635\u0648\u0631\u062a \u067e\u0634\u062a\u06cc\u0628\u0627\u0646\u06cc) \u0645\u06cc\u200c\u0645\u0627\u0646\u062f. \u0633\u0631\u0648\u06cc\u0633\u200c\u0648\u0631\u06a9\u0631 \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0641\u0627\u06cc\u0644 \u062f\u0631\u0633 \u0631\u0627 \u0628\u0631\u0627\u06cc \u0622\u0641\u0644\u0627\u06cc\u0646 \u0646\u06af\u0647 \u062f\u0627\u0631\u062f. \u0627\u06cc\u0646 \u0630\u062e\u06cc\u0631\u0647 \u0628\u0631\u0627\u06cc \u06a9\u0627\u0631\u06a9\u0631\u062f \u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a \u0648 \u0628\u0646\u0631 \u0631\u0636\u0627\u06cc\u062a \u06a9\u0648\u06a9\u06cc PECR \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a. \u067e\u0627\u06a9\u200c\u06a9\u0631\u062f\u0646 \u062f\u0627\u062f\u0647 \u06cc\u0627 \u062f\u06a9\u0645\u0647\u0654 \xab\u062d\u0630\u0641 \u062f\u0627\u062f\u0647\u200c\u0647\u0627\u06cc \u0645\u0646\xbb \u0622\u0646 \u0631\u0627 \u067e\u0627\u06a9 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0645\u0627 \u0628\u0627\u0632\u0646\u0645\u06cc\u200c\u06af\u0631\u062f\u0627\u0646\u06cc\u0645.")
B.amM=new A.bS("Liability","Provided as is during beta. Nothing limits liability that cannot be limited by law, or your statutory consumer rights under the Consumer Rights Act 2015.","\u062f\u0631 \u0628\u062a\u0627 \xab\u0647\u0645\u0627\u0646\u200c\u0637\u0648\u0631 \u06a9\u0647 \u0647\u0633\u062a\xbb. \u062d\u0642\u0648\u0642 \u0642\u0627\u0646\u0648\u0646\u06cc \u0645\u0635\u0631\u0641\u200c\u06a9\u0646\u0646\u062f\u0647 \u062a\u062d\u062a CRA 2015 \u0645\u062d\u062f\u0648\u062f \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.")
